CREATE PROCEDURE usp_UpdateCredit (@CustID INT, @NewLimit DECIMAL)
AS
BEGIN
    UPDATE Customers SET CreditLimit = @NewLimit WHERE CustomerID = @CustID;
    EXEC usp_LogChange @CustID, @NewLimit;
END

